import React, { useState } from "react";
import { Bar, Pie } from "react-chartjs-2";
import "chart.js/auto";

function App() {
  const [ivaData, setIvaData] = useState(null);

  const uploadXML = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("xml", file);

    const res = await fetch("http://localhost:4000/upload", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    setIvaData(data);
  };

  const chartData = ivaData
    ? {
        labels: ["0%", "1%", "2%", "13%"],
        datasets: [
          {
            label: "Monto Base",
            data: [
              ivaData.montoBase0,
              ivaData.montoBase1,
              ivaData.montoBase2,
              ivaData.montoBase13,
            ],
            backgroundColor: ["#4CAF50", "#2196F3", "#FF9800", "#E91E63"],
          },
        ],
      }
    : null;

  const pieData = ivaData
    ? {
        labels: ["IVA 1%", "IVA 2%", "IVA 13%"],
        datasets: [
          {
            data: [
              ivaData.iva1,
              ivaData.iva2,
              ivaData.iva13,
            ],
            backgroundColor: ["#2196F3", "#FF9800", "#E91E63"],
          },
        ],
      }
    : null;

  return (
    <div style={{ padding: "30px", fontFamily: "Arial" }}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>
        Dashboard de Facturas XML – IVA
      </h1>

      <input type="file" accept=".xml" onChange={uploadXML} />

      {ivaData && (
        <>
          <h2 style={{ marginTop: "30px" }}>Totales</h2>
          <div style={{ display: "flex", gap: "20px" }}>

            <div style={cardStyle}>
              <h3>IVA 1%</h3>
              <p>IVA: {ivaData.iva1.toFixed(2)}</p>
              <p>Monto Base: {ivaData.montoBase1.toFixed(2)}</p>
            </div>

            <div style={cardStyle}>
              <h3>IVA 2%</h3>
              <p>IVA: {ivaData.iva2.toFixed(2)}</p>
              <p>Monto Base: {ivaData.montoBase2.toFixed(2)}</p>
            </div>

            <div style={cardStyle}>
              <h3>IVA 13%</h3>
              <p>IVA: {ivaData.iva13.toFixed(2)}</p>
              <p>Monto Base: {ivaData.montoBase13.toFixed(2)}</p>
            </div>
          </div>

          <h2 style={{ marginTop: "40px" }}>Gráficos</h2>

          <div
            style={{
              display: "flex",
              gap: "40px",
              flexWrap: "wrap",
              justifyContent: "center",
            }}
          >
            <div style={{ width: "45%", minWidth: "300px" }}>
              <h3>Montos Base</h3>
              <Bar data={chartData} />
            </div>

            <div style={{ width: "45%", minWidth: "300px" }}>
              <h3>Distribución del IVA</h3>
              <Pie data={pieData} />
            </div>
          </div>
        </>
      )}
    </div>
  );
}

const cardStyle = {
  background: "#fff",
  padding: "20px",
  borderRadius: "12px",
  boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
  width: "200px",
};

export default App;
